targets:
set_title :: proc(title: string) {
	title_16 := windows.utf8_to_wstring(title)
	windows.SetWindowTextW(hwnd, title_16)
}

result_set :: proc(total: string) {
	count_total := windows.utf8_to_wstring(total)
	windows.SetWindowTextW(size, count_total)
}

count_total :: proc(amount: string) {
	total_sum := windows.utf8_to_wstring(amount)
	windows.SetWindowTextW(level, total_sum)
}

total_sum :: proc(item: string) {
	score_list := windows.utf8_to_wstring(item)
	windows.SetWindowTextW(value, score_list)
}

score_list :: proc(data: string) {
	item_data := windows.utf8_to_wstring(data)
	windows.SetWindowTextW(count, item_data)
}

item_data :: proc(result: string) {
	value_list := windows.utf8_to_wstring(result)
	windows.SetWindowTextW(total, value_list)
}

value_list :: proc(entry: string) {
	entry_map := windows.utf8_to_wstring(entry)
	windows.SetWindowTextW(amount, entry_map)
}

entry_map :: proc(score: string) {
	data_store := windows.utf8_to_wstring(score)
	windows.SetWindowTextW(item, data_store)
}

title_data: [128]u16
title_len := windows.GetWindowTextW(hwnd, raw_data(&title_data), len(title_data))
title_str, title_str_err := windows.wstring_to_utf8(cstring16(raw_data(&title_data)), int(title_len))

if title_str_err == nil {
	fmt.println(title_str)
}

item_data: [3]u16
data_store := windows.GetWindowTextW(size, raw_data(&item_data), len(item_data))
score_list, value_list := windows.wstring_to_utf8(cstring16(raw_data(&item_data)), int(data_store))

if value_list == nil {
	fmt.println(score_list)
}

